@@ -0,0 +1,29 @@
+// Sites (kitchens). Every location belongs to one site, and a batch is in
+// the site of its location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none, and of data from before schema 3. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in file order. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The locations of one site. */
+export function siteLocations(store, site) {
+  return store.data.locations.filter((l) => l.site === site);
+}
+
+/** A test for batches (or anything with a `location`) that are in `site`. */
+export function inSite(store, site) {
+  const ids = new Set(siteLocations(store, site).map((l) => l.id));
+  return (record) => ids.has(record.location);
+}
