+import test from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { migrate } from "../src/db/migrations.js";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+const post = (path, body, headers = {}) => ({ method: "POST", path, body, headers });
+
+// Puts 3 l of milk in the annex fridge by receiving the seed's sent order 2 there.
+async function stockAnnex(handle) {
+  const res = await handle(post("/orders/2/receive", { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }, { lot: "AX-2", expires: null, location: "annex-fridge" }] }, annex));
+  assert.equal(res.status, 200);
+  return res.body.batches;
+}
+
+test("schema 2 files open with every location in site main", () => {
+  const { sites, ...old } = JSON.parse(readFileSync(new URL("../data/seed.json", import.meta.url), "utf8"));
+  const locations = old.locations.filter((l) => l.site === "main").map(({ site, kind, ...l }) => l);
+  const data = migrate({ ...old, schemaVersion: 2, locations });
+  assert.deepEqual(data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.ok(data.locations.every((l) => l.site === "main"));
+  assert.deepEqual(data.locations.map((l) => l.kind), ["fridge", "freezer", "dry"]);
+  assert.equal(data.batches.length, old.batches.length);
+});
+
+test("the site comes from X-Larder-Site and defaults to main", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/batches" })).body.length, 9);
+  assert.equal((await handle({ path: "/batches", headers: { "x-larder-site": "main" } })).body.length, 9);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "cellar" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
